const b = $input.first().json.body || {};
const reply = (o) => [{ json: o }];
let site = String(b.website || '').trim();
if (!site) return reply({ valid: false, error: 'Field "website" is required.' });
if (!/^https?:\/\//i.test(site)) site = 'https://' + site;
// No URL class here: parse by regex so it also works in the task runner sandbox.
const m = site.match(/^(https?:\/\/)([^\/?#:@\s]+)(:\d+)?([\/?#].*)?$/i);
if (!m) return reply({ valid: false, error: '"website" is not a valid URL.' });
const h = m[2].toLowerCase();
const local = h === 'localhost' || !h.includes('.') ||
  /^(127|10|0)\./.test(h) || /^192\.168\./.test(h) || /^169\.254\./.test(h) ||
  /^172\.(1[6-9]|2\d|3[01])\./.test(h);
if (local) return reply({ valid: false, error: 'Private or local addresses are not allowed.' });
return reply({
  valid: true,
  website: site,
  origin: m[1].toLowerCase() + h + (m[3] || ''),
  organization: String(b.organization || '').trim(),
  reference_id: b.reference_id === undefined ? null : b.reference_id,
});

// Find the Impressum link. Three strategies, last one is a guess.
const html = String($input.first().json.data || $input.first().json.body || '');
const v = $('Validate Input').first().json;
const origin = v.origin;
const abs = (u) => u.startsWith('http') ? u : (u.startsWith('//') ? 'https:' + u
  : (u.startsWith('/') ? origin + u : origin + '/' + u));

let url = null;
// 1) normal links, href containing impressum / imprint / legal notice
const re = /href=["']([^"']*(?:impressum|imprint|legal-notice|rechtliches)[^"']*)["']/gi;
let m;
while ((m = re.exec(html)) !== null) {
  if (!/^(mailto|tel|javascript):/i.test(m[1])) { url = abs(m[1]); break; }
}
// 2) JSON-embedded links on SPA sites: URL near the word "Impressum"
if (!url) {
  const idx = html.toLowerCase().indexOf('impressum');
  if (idx >= 0) {
    const win = html.substring(Math.max(0, idx - 500), idx + 500);
    const found = win.match(/https?:\/\/[^\s"\\,})]+/g);
    if (found && found.length) url = found[0];
  }
}
// 3) guess
if (!url) url = origin + '/impressum';

return [{ json: { impressum_url: url } }];

// HTML -> plain text, capped for the LLM.
const html = String($input.first().json.data || $input.first().json.body || '');
const text = html
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<[^>]+>/g, '\n')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ').replace(/&#\d+;/g, '')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n+/g, '\n')
  .trim();

const ok = text.length >= 50;
return [{ json: {
  has_content: ok,
  impressum_text: ok ? text.slice(0, 8000) : '',
  impressum_url: $('Find Impressum URL').first().json.impressum_url,
} }];

// Keep only values that literally appear in the page text.
const v = $('Validate Input').first().json;
const page = $('Clean Page Text').first().json;
const reply = (o) => [{ json: Object.assign({
  status: 'ok', reference_id: v.reference_id, website: v.website,
  impressum_url: page.impressum_url || null }, o) }];

if (!page.has_content) {
  return reply({ data: {}, dropped_fields: [], reason: 'no_content' });
}

let raw = {};
try {
  const ai = $input.first().json;
  const content = (ai.choices && ai.choices[0] && ai.choices[0].message && ai.choices[0].message.content) || '{}';
  raw = JSON.parse(content);
} catch (e) { raw = {}; }

const text = page.impressum_text;
const norm = (s) => String(s).toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '');
const hay = norm(text);
const hayDigits = text.replace(/\D/g, '');
const hayCompact = text.toUpperCase().replace(/\s+/g, '');

const checks = {
  company_name: (x) => hay.includes(norm(x)),
  legal_form: (x) => hay.includes(norm(x)),
  street: (x) => hay.includes(norm(x)),
  postal_code: (x) => hayDigits.includes(String(x).replace(/\D/g, '')) && String(x).replace(/\D/g, '').length >= 4,
  city: (x) => hay.includes(norm(x)),
  country: () => true,
  // must look like an address AND appear in the text ("[email protected]" placeholders fail the first test)
  email: (x) => /^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$/.test(String(x)) &&
    text.toLowerCase().includes(String(x).toLowerCase()),
  phone: (x) => {
    const d = String(x).replace(/\D/g, '').replace(/^(00)?49/, '').replace(/^0+/, '');
    return d.length >= 6 && hayDigits.includes(d);
  },
  vat_id: (x) => hayCompact.includes(String(x).toUpperCase().replace(/\s+/g, '')),
  register_court: (x) => hay.includes(norm(x)),
  register_number: (x) => {
    const d = (String(x).match(/\d{3,}/) || [''])[0];
    return d !== '' && hayDigits.includes(d);
  },
};

const data = {};
const dropped = [];
for (const [k, fn] of Object.entries(checks)) {
  if (raw[k] === undefined || raw[k] === null || raw[k] === '') continue;
  if (fn(raw[k])) data[k] = raw[k]; else dropped.push(k);
}
if (Array.isArray(raw.representatives)) {
  const reps = [];
  for (const r of raw.representatives) {
    if (r && r.name && hay.includes(norm(r.name))) {
      reps.push({ name: String(r.name), role: r.role ? String(r.role) : null });
    } else if (r && r.name) {
      dropped.push('representatives: ' + r.name);
    }
  }
  if (reps.length) data.representatives = reps;
}

return reply({ data, dropped_fields: dropped, reason: Object.keys(data).length ? null : 'nothing_verified' });
